// src/pages/Community.js

import { useNavigate } from "react-router-dom";
import { useState } from "react";

function Community() {
  const navigate = useNavigate();

  const [meetings, setMeetings] = useState([
    {
      title: "헤밍웨이 심층 토론",
      book: "노르웨이의 숲",
      date: "2026-03-12",
      time: "19:00",
      people: "5/8명",
      mood: "badge1",
    },

    {
      title: "퇴근 후 가볍게",
      book: "데미안",
      date: "2026-03-13",
      time: "21:00",
      people: "3/6명",
      mood: "badge2",
    },

    {
      title: "감성 문장 수집",
      book: "어린왕자",
      date: "2026-03-14",
      time: "20:00",
      people: "7/10명",
      mood: "badge3",
    },
  ]);

  const [showForm, setShowForm] =
    useState(false);

  const [searchBook, setSearchBook] =
    useState("");

  const bookList = [
    "노르웨이의 숲",
    "데미안",
    "어린왕자",
    "1984",
    "해변의 카프카",
    "채식주의자",
  ];

  const [newMeeting, setNewMeeting] =
    useState({
      name: "",
      book: "",
      date: "",
      time: "",
      maxPeople: "",
      mood: "badge1",
    });

  const getMoodText = (mood) => {
    if (mood === "badge1")
      return "깊게 토론해요";

    if (mood === "badge2")
      return "부담없이 참여해요";

    return "함께 이야기해요";
  };

  const createMeeting = () => {
    if (
      !newMeeting.name ||
      !newMeeting.book ||
      !newMeeting.date ||
      !newMeeting.time
    )
      return;

    const newItem = {
      title: newMeeting.name,
      book: newMeeting.book,
      date: newMeeting.date,
      time: newMeeting.time,
      people: `1/${newMeeting.maxPeople}명`,
      mood: newMeeting.mood,
    };

    setMeetings([
      newItem,
      ...meetings,
    ]);

    setShowForm(false);

    setNewMeeting({
      name: "",
      book: "",
      date: "",
      time: "",
      maxPeople: "",
      mood: "badge1",
    });

    setSearchBook("");
  };

  return (
    <div className="page">
      <div className="community-header">
        <div className="logo">
          READLY
        </div>

        <button
          className="create-btn"
          onClick={() =>
            setShowForm(!showForm)
          }
        >
          + 모임 만들기
        </button>
      </div>

      <div className="community-guide">
        모임 시작 10분 전까지
        참여할 수 있어요 📚
      </div>

      {/* 모임 생성 */}

      {showForm && (
        <div className="create-form">

          {/* 모임 이름 */}

          <input
            placeholder="모임 이름"
            value={newMeeting.name}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                name: e.target.value,
              })
            }
          />

          {/* 책 검색 */}

          <input
            placeholder="책 제목 검색"
            value={searchBook}
            onChange={(e) =>
              setSearchBook(
                e.target.value
              )
            }
          />

          {/* 검색 결과 */}

          <div className="book-search-list">
            {bookList
              .filter((book) =>
                book.includes(
                  searchBook
                )
              )
              .map((book, index) => (
                <div
                  key={index}
                  className="book-search-item"
                  onClick={() =>
                    setNewMeeting({
                      ...newMeeting,
                      book,
                    })
                  }
                >
                  📖 {book}
                </div>
              ))}
          </div>

          {/* 선택 책 */}

          {newMeeting.book && (
            <div className="selected-book">
              선택한 책 :
              {" "}
              {newMeeting.book}
            </div>
          )}

          {/* 날짜 */}

          <input
            type="date"
            value={newMeeting.date}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                date: e.target.value,
              })
            }
          />

          {/* 시간 */}

          <input
            type="time"
            value={newMeeting.time}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                time: e.target.value,
              })
            }
          />

          {/* 인원 */}

          <input
            type="number"
            placeholder="최대 인원"
            value={
              newMeeting.maxPeople
            }
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                maxPeople:
                  e.target.value,
              })
            }
          />

          {/* 스타일 */}

          <select
            value={newMeeting.mood}
            onChange={(e) =>
              setNewMeeting({
                ...newMeeting,
                mood: e.target.value,
              })
            }
          >
            <option value="badge1">
              깊게 토론해요
            </option>

            <option value="badge2">
              부담없이 참여해요
            </option>

            <option value="badge3">
              함께 이야기해요
            </option>
          </select>

          <button
            className="submit-btn"
            onClick={createMeeting}
          >
            모임 생성하기
          </button>
        </div>
      )}

      {/* 모임 리스트 */}

      <div className="meeting-list">
        {meetings.map(
          (meeting, index) => {
            const today =
              new Date();

            const meetingDate =
              new Date(
                `${meeting.date}T${meeting.time}`
              );

            const isFuture =
              meetingDate > today;

            return (
              <div
                className="meeting-card"
                key={index}
              >
                <div className="meeting-top">
                  <div>
                    <div className="meeting-book">
                      📚 {meeting.title}
                    </div>

                    <div className="meeting-sub-book">
                      {meeting.book}
                    </div>

                    <div className="meeting-time">
                      {meeting.date}
                      {" · "}
                      {meeting.time}
                    </div>
                  </div>

                  <div
                    className={
                      meeting.mood
                    }
                  >
                    {getMoodText(
                      meeting.mood
                    )}
                  </div>
                </div>

                <div className="meeting-bottom">
                  <div className="meeting-member">
                    👥{" "}
                    {meeting.people}
                  </div>

                  {isFuture ? (
                    <div className="before-start">
                      시작 전
                    </div>
                  ) : (
                    <button
                      className="join-btn"
                      onClick={() =>
                        navigate(
                          "/meeting",
                          {
                            state: {
                              title:
                                meeting.title,
                              mood:
                                meeting.mood,
                            },
                          }
                        )
                      }
                    >
                      참여하기
                    </button>
                  )}
                </div>
              </div>
            );
          }
        )}
      </div>
    </div>
  );
}

export default Community;
